# Kaggle next-action probe runner: replays recorded sessions to decision points and samples one more model
# turn per (variant, point, sample) with the official ADK stack. Generated by scripts/make_probe_kernel.py.
import asyncio
import base64
import glob
import gzip
import json
import logging
import os
import shutil
import subprocess
import sys
import time
from pathlib import Path

VARIANTS_B64 = json.loads(base64.b64decode("__VARIANTS_B64__").decode())
POINTS = json.loads(gzip.decompress(base64.b64decode("__POINTS_B64__")).decode())
RUN = json.loads(base64.b64decode("__RUN_B64__").decode())
RUNNER_SRC = base64.b64decode("__RUNNER_B64__").decode()
STUB_SRC = base64.b64decode("__STUB_B64__").decode()
T0 = time.time()


def log(msg):
    print(f"[{(time.time() - T0) / 60:6.1f}m] {msg}", flush=True)


os.environ.update({
    'TRANSFORMERS_NO_TF': '1', 'TRANSFORMERS_NO_FLAX': '1', 'TRANSFORMERS_OFFLINE': '1',
    'VLLM_NO_USAGE_STATS': '1', 'VLLM_WORKER_MULTIPROC_METHOD': 'spawn',
    'VLLM_ENGINE_READY_TIMEOUT_S': '1200', 'VLLM_MEMORY_PROFILER_ESTIMATE_CUDAGRAPHS': '1',
    'NCCL_DEBUG': 'WARN', 'LITELLM_LOCAL_MODEL_COST_MAP': 'True', 'LITELLM_TELEMETRY': 'False',
    'LITELLM_LOG': 'WARNING', 'OPENAI_API_KEY': 'EMPTY', 'LOCAL_API_KEY': 'EMPTY',
    'PYTORCH_CUDA_ALLOC_CONF': 'expandable_segments:True', 'OTEL_SDK_DISABLED': 'true',
    'OTEL_PYTHON_DISABLED': 'true',
})
for name in ('LiteLLM', 'LiteLLM Router', 'LiteLLM Proxy', 'litellm', 'httpx', 'httpcore', 'openai',
             'urllib3', 'opentelemetry', 'opentelemetry.context'):
    lg = logging.getLogger(name)
    lg.setLevel(logging.WARNING)
    if 'litellm' in name.lower():
        lg.propagate = False
        lg.handlers.clear()

# ---------------------------------------------------------------- install harness (same as starter)
WHEELHOUSE = Path(glob.glob('/kaggle/input/**/gemma-4-developer-agent-wheelhouse', recursive=True)[0])
for pth_pattern in ('/usr/local/lib/python*/dist-packages/*cutlass*.pth',
                    '/usr/local/lib/python*/site-packages/*cutlass*.pth'):
    for pth in glob.glob(pth_pattern):
        try:
            os.unlink(pth)
        except OSError:
            pass
tmp_whl = Path('/tmp/wheelhouse')
tmp_whl.mkdir(parents=True, exist_ok=True)
for w in WHEELHOUSE.glob('*.whl'):
    if 'cutlass' in w.name.lower():
        continue
    target = tmp_whl / (w.name.replace('cu128', '+cu128') if ('cu128' in w.name and '+' not in w.name) else w.name)
    if not target.exists():
        try:
            os.symlink(w, target)
        except OSError:
            shutil.copyfile(w, target)
subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', '--no-deps', '--force-reinstall',
                *sorted(str(w) for w in tmp_whl.glob('*.whl'))], check=True)
log("wheels installed")

WORK = Path('/kaggle/working')
variants = {}
for vname, files in VARIANTS_B64.items():
    d = WORK / 'bundles' / vname
    shutil.rmtree(d, ignore_errors=True)
    for rel, b64 in files.items():
        p = d / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
    variants[vname] = str(d)
(WORK / 'probe_runner.py').write_text(RUNNER_SRC)
sys.path.insert(0, str(WORK))
log(f"variants {sorted(variants)}  points {len(POINTS)}  run={RUN}")

import litellm  # noqa: E402
from adk_submission import validate_directory  # noqa: E402
from adk_submission.discovery import discover_declared_models  # noqa: E402
from swegemma.config import build_submission_limits  # noqa: E402

import probe_runner  # noqa: E402

litellm.drop_params = True
limits, _ = build_submission_limits()
models_declared = set()
for d in variants.values():
    validate_directory(d, limits=limits)
    models_declared |= set(discover_declared_models(d))
assert len(models_declared) == 1, models_declared
model_name = next(iter(models_declared))

server = None
if RUN.get('mode') == 'stub':
    import socket  # noqa: E402
    from google.adk.models.lite_llm import LiteLlm  # noqa: E402
    (WORK / 'stub_llm_server.py').write_text(STUB_SRC)
    subprocess.Popen([sys.executable, str(WORK / 'stub_llm_server.py'), '--port', '8012',
                      '--log', str(WORK / 'stub_requests.jsonl')])
    for _ in range(60):
        try:
            socket.create_connection(('127.0.0.1', 8012), timeout=1).close()
            break
        except OSError:
            time.sleep(1)
    real = LiteLlm(model=f'openai/{model_name}', api_base='http://127.0.0.1:8012/v1', api_key='EMPTY',
                   num_retries=1)
else:
    from adk_submission import VllmConfig, VllmServer  # noqa: E402
    MODEL_PATH = Path(glob.glob(f'/kaggle/input/**/{model_name}/*/config.json', recursive=True)[0]).parent
    server = VllmServer(VllmConfig(
        model=str(MODEL_PATH), port=8000, host='127.0.0.1', tool_call_parser='gemma4', reasoning_parser='gemma4',
        max_model_len=32768, dtype='bfloat16', gpu_memory_utilization=0.90, enable_auto_tool_choice=True,
        scheduler_reserve_full_isl=False,
        tensor_parallel_size=min(4, __import__('torch').cuda.device_count()), startup_timeout=60 * 20,
    ))
    server.start()
    real = server.create_model_registry(aliases=[model_name], model_prefix='openai/',
                                        api_key='EMPTY').get(model_name)
    log("vLLM up")

OUT = WORK / 'probe.jsonl'
OUT.unlink(missing_ok=True)
asyncio.run(probe_runner.run_all(POINTS, variants, real, model_name, str(OUT), samples=int(RUN.get('samples', 1)),
                                 concurrency=int(RUN.get('concurrency', 16)), log=log))
n = sum(1 for _ in open(OUT))
log(f"DONE {n} probe results -> {OUT}")
if server is not None:
    try:
        server.stop()
    except Exception:  # noqa: BLE001
        pass
